def copiar_estado_a_entregas(apps, schema_editor):
    # El estado era uno solo por tarea: se conserva como el avance de cada alumno que la tenía asignada.
    # Las tareas pendientes no necesitan registro (sin entrega, la tarea está pendiente para el alumno).
    Tarea = apps.get_model('coordinacion', 'Tarea')
    EntregaTarea = apps.get_model('coordinacion', 'EntregaTarea')
    EntregaTarea.objects.bulk_create([
        EntregaTarea(tarea=tarea, estudiante=estudiante, estado=tarea.estado)
        for tarea in Tarea.objects.exclude(estado='pendiente').prefetch_related('estudiantes')
        for estudiante in tarea.estudiantes.all()
    ])


